 $('preset-form').addEventListener('submit',e=>{e.preventDefault();let f=e.currentTarget.elements,amount=amountCents(f.amount.value),id=f.id.value,name=f.name.value.trim();if(!name||name.length>100||!Number.isSafeInteger(amount)||amount<1){$('preset-error').textContent='Enter a name and a positive amount.';return}let old=id&&state.recurringMustPays.find(x=>x.id===id),next={id:old?.id||uid(),name,amountCents:amount,enabled:old?.enabled!==false,createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};if(old)Object.assign(old,next);else state.recurringMustPays.push(next);persist();$('preset-dialog').close();renderRecurringMustPays();flash('Recurring must pay saved.')});
