 let breakdown=$('allocation-summary');breakdown.replaceChildren();for(const kind of ['must','debt','savings']){let r=node('div',undefined,'row');r.append(node('span',kind==='must'?'Must pays':kind==='debt'?'Debt payments':'Savings'),node('strong',money(allocationTotal(p,kind))));breakdown.append(r);let list=$(kind+'-list');list.replaceChildren();let entries=state.allocations.filter(a=>a.payPeriodId===p.id&&a.kind===kind);if(!entries.length){empty(list,'Nothing recorded yet.');continue}for(const a of entries){let item=node('div',undefined,'item'),main=node('div',a.reason,'item-main'),side=node('div',undefined,'item-side');side.append(node('strong',money(a.amountCents)));let actions=node('div',undefined,'item-actions');for(const [label,fn] of [['Edit',()=>openAllocation(kind,a)],['Delete',()=>deleteAllocation(a)]]){let button=node('button',label,'text-button');button.type='button';button.addEventListener('click',fn);actions.append(button)}side.append(actions);item.append(main,side);list.append(item)}}
