function closeDay(kind){let p=active(),date=$('no-spend-date').value;if(!p||!dateValid(date)||!inPeriod(p,date)||date>today())return;let purchases=state.transactions.some(t=>t.payPeriodId===p.id&&t.transactionDate.slice(0,10)===date);if(kind==='no-spend'&&purchases){flash('This day has a purchase; confirm purchases logged instead.',true);return}state.noSpendDays=state.noSpendDays.filter(x=>!(x.payPeriodId===p.id&&x.date===date));state.dailyCheckins=state.dailyCheckins.filter(x=>!(x.payPeriodId===p.id&&x.date===date));let onTime=date===today(),record={date,payPeriodId:p.id,confirmedAt:new Date().toISOString(),onTime};if(kind==='no-spend')state.noSpendDays.push(record);else state.dailyCheckins.push(record);let earned=onTime?awardStreaks(date):[];persist();render();flash(`${onTime?(kind==='no-spend'?'Gold day recorded.':'Blue day recorded.'):'Catch-up day recorded in purple.'}${earned.length?' Milestone: '+earned.join(', ')+'.':''}`)} 
