$('export-allocations').addEventListener('click',()=>{let rows=state.allocations.map(a=>{let p=state.periods.find(x=>x.id===a.payPeriodId);return [a.kind,(a.amountCents/100).toFixed(2),currencyFor(p),a.reason,p.id,`${p.startDate} to ${p.nextPayday}`]});download(`money-until-payday-allocations-${today()}.csv`,'\ufeff'+[['Type','Amount','Currency','Reason / debt','Pay period ID','Pay period label'],...rows].map(row=>row.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8')});
$('import-json').addEventListener('change',async e=>{let file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>10*1024*1024){flash('Backup is larger than 10 MB.',true);return}try{let imported=validateBackup(JSON.parse(await file.text()));if(!confirm('Replace all current periods, purchases, and settings with this backup? Export your current data first if needed.'))return;let old=state;state=imported;if(!persist()){state=old;return}render();setView('dashboard');prefillPeriod();flash('Backup restored.')}catch(err){flash(err.message||'Could not read backup.',true)}});
function prefillPeriod(){if(active())return;let last=state.periods.at(-1),start=last&&last.nextPayday<=today()?last.nextPayday:today();let next=last&&last.nextPayday>today()?last.nextPayday:shift(start,state.settings.paydayCadenceDays);if(next<=today())next=shift(today(),state.settings.paydayCadenceDays);let f=$('period-form').elements;f.startDate.value=start;f.nextPayday.value=next;f.allowance.value=state.settings.defaultAllowanceCents===null?'':(state.settings.defaultAllowanceCents/100).toFixed(2);f.payAmount.value=last?.payAmountCents&&currencyFor(last)===state.settings.currency? (last.payAmountCents/100).toFixed(2):''}
$('add').addEventListener('click',()=>openPurchase());document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));document.querySelector('[data-close]').addEventListener('click',()=>$('purchase-dialog').close());$('purchase-dialog').addEventListener('click',e=>{if(e.target===$('purchase-dialog'))e.target.close()});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('install').hidden=false});$('install').addEventListener('click',async()=>{if(!installPrompt)return;installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('install').hidden=true});window.addEventListener('appinstalled',()=>$('install').hidden=true);
try{let raw=localStorage.getItem(KEY);if(raw){state=validateBackup(JSON.parse(raw));if(JSON.parse(raw).version<5)persist()}}catch{state=initial();flash('Saved data could not be read. Export any older backup before entering new data.',true)}
render();renderRecurringMustPays();renderDebts();prefillPeriod();if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(()=>{}));
function dayStatus(p,date){let record=checkinRecord(p,date);if(record)return record.onTime===false?'late':state.noSpendDays.includes(record)?'no-spend':'logged';if((state.clearedCheckins||[]).some(c=>c.payPeriodId===p.id&&c.date===date))return 'pending';let createdDate=p.createdAt?localDate(new Date(p.createdAt)):p.startDate;if(date>=today()||date<createdDate)return 'pending';return state.transactions.every(t=>t.payPeriodId!==p.id||t.transactionDate.slice(0,10)!==date)?'no-spend':'pending'}
function renderCheckins(p,now){const picker=$('no-spend-date'),grid=$('day-grid');if(picker){picker.closest('label')?.setAttribute('hidden','');picker.value=selectedCheckinDate||picker.value||today()}const selected=picker?.value||selectedCheckinDate;selectedCheckinDate=selected;grid.replaceChildren();const total=daysBetween(p.startDate,p.nextPayday);for(let i=0;i<total;i++){let date=shift(p.startDate,i),status=dayStatus(p,date),future=date>now,button=node('button',String(i+1),'day-tile '+(future?'future':status)+(date===selected?' selected':''));button.type='button';button.disabled=future;button.title=`${formatDate(date)}: ${future?'upcoming':status==='no-spend'?'No spending':'All purchases logged'}`;button.setAttribute('aria-label',button.title);button.append(node('small',date.slice(5)));if(!future)button.addEventListener('click',()=>{selectedCheckinDate=date;if(picker)picker.value=date;renderCheckins(p,today())});grid.append(button)}const stats=checkinStats(p);$('checkin-count').textContent=`${stats.checked} of ${stats.total} checked · ${stats.onTime} on time`;$('mark-logged').disabled=!selected||selected>today();$('mark-day').hidden=true;$('clear-day').disabled=!selected||dayStatus(p,selected)==='pending';$('mark-help').textContent=!selected?'Select a day above.':`Selected: ${formatDate(selected)} · ${dayStatus(p,selected)==='no-spend'?'No spending':'All purchases logged'}${state.transactions.some(t=>t.payPeriodId===p.id&&t.transactionDate.slice(0,10)===selected)?' · Purchases recorded.':''}`}
function closeDay(kind){let p=active(),date=$('no-spend-date')?.value;if(kind!=='logged'||!p||!dateValid(date)||!inPeriod(p,date)||date>today())return;let hasPurchases=state.transactions.some(t=>t.payPeriodId===p.id&&t.transactionDate.slice(0,10)===date);state.noSpendDays=state.noSpendDays.filter(x=>!(x.payPeriodId===p.id&&x.date===date));state.dailyCheckins=state.dailyCheckins.filter(x=>!(x.payPeriodId===p.id&&x.date===date));state.clearedCheckins=(state.clearedCheckins||[]).filter(x=>!(x.payPeriodId===p.id&&x.date===date));let record={date,payPeriodId:p.id,confirmedAt:new Date().toISOString(),onTime:hasPurchases?date===today():true};if(hasPurchases)state.dailyCheckins.push(record);else state.noSpendDays.push(record);let earned=hasPurchases&&record.onTime?awardStreaks(date):[];persist();render();flash(`${hasPurchases?(record.onTime?'Blue day recorded.':'Catch-up day recorded in purple.'):'Gold no-spend day recorded.'}${earned.length?' Milestone: '+earned.join(', ')+'.':''}`)}
function monthShift(date,months){let source=new Date(dateUTC(date)),day=source.getUTCDate(),target=new Date(Date.UTC(source.getUTCFullYear(),source.getUTCMonth()+months,1)),last=new Date(Date.UTC(target.getUTCFullYear(),target.getUTCMonth()+1,0)).getUTCDate();target.setUTCDate(Math.min(day,last));return target.toISOString().slice(0,10)}
function presetAnchorDate(preset){let date=preset.anchorDate||today();return preset.anchorType==='last'?(preset.cadence||'bi-weekly')==='monthly'?monthShift(date,1):shift(date,14):date}
function presetDueDateInPeriod(preset,period){let due=presetAnchorDate(preset),cadence=preset.cadence||'bi-weekly';while(due<period.startDate)due=cadence==='monthly'?monthShift(due,1):shift(due,14);return due<period.nextPayday?due:null}
function addRecurringMustPaysForPeriod(period){if(!period||!period.id)return;for(const preset of state.recurringMustPays.filter(p=>p.enabled!==false)){if(!presetDueDateInPeriod(preset,period))continue;const exists=state.allocations.some(a=>a.payPeriodId===period.id&&a.kind==='must'&&a.sourcePresetId===preset.id);if(exists)continue;state.allocations.push({id:uid(),payPeriodId:period.id,kind:'must',amountCents:preset.amountCents,reason:preset.name,sourcePresetId:preset.id,dueDate:presetDueDateInPeriod(preset,period),createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()})}}
function openPreset(preset){const form=$('preset-form');form.reset();form.elements.id.value=preset?.id||'';form.elements.name.value=preset?.name||'';form.elements.amount.value=preset?(preset.amountCents/100).toFixed(2):'';form.elements.cadence.value=preset?.cadence||'bi-weekly';form.elements.anchorType.value=preset?.anchorType||'next';form.elements.anchorDate.value=preset?.anchorDate||today();$('preset-title').textContent=preset?'Edit recurring must pay':'Add recurring must pay';$('preset-error').textContent='';$('preset-dialog').showModal()}
function renderRecurringMustPays(){const list=$('preset-list');if(!list)return;list.replaceChildren();if(!state.recurringMustPays.length){empty(list,'No recurring must pays yet.');return}for(const preset of state.recurringMustPays){let cadence=preset.cadence||'bi-weekly',anchor=preset.anchorDate?formatDate(preset.anchorDate):'Set payment date',row=node('div',undefined,'item'),main=node('div',undefined,'item-main'),side=node('div',undefined,'item-side');main.append(node('div',preset.name,'item-title'),node('div',`${money(preset.amountCents)} · ${cadence==='monthly'?'Monthly':'Every two weeks'} · ${anchor}`,'item-sub'));side.append(node('strong',money(preset.amountCents)));let actions=node('div',undefined,'item-actions');for(const [label,fn] of [['Edit',()=>openPreset(preset)],['Toggle',()=>{preset.enabled=preset.enabled===false;preset.updatedAt=new Date().toISOString();persist();renderRecurringMustPays();flash('Recurring must pay updated.')}],['Delete',()=>{if(!confirm(`Delete recurring must pay “${preset.name}”?`))return;state.recurringMustPays=state.recurringMustPays.filter(x=>x.id!==preset.id);persist();renderRecurringMustPays();flash('Recurring must pay deleted.')}]] ){let button=node('button',label,'text-button');button.type='button';button.addEventListener('click',fn);actions.append(button)}side.append(actions);row.append(main,side);list.append(row)}}
function bindFeatureDialogs(){ $('add-preset').addEventListener('click',()=>openPreset());$('add-debt').addEventListener('click',()=>openDebt());$('preset-form').addEventListener('submit',e=>{e.preventDefault();let f=e.currentTarget.elements,amount=amountCents(f.amount.value),name=f.name.value.trim(),id=f.id.value,anchorDate=f.anchorDate.value;if(!name||name.length>100||!Number.isSafeInteger(amount)||amount<1||!dateValid(anchorDate)){ $('preset-error').textContent='Enter a name, positive amount, and valid payment date.';return}let old=id&&state.recurringMustPays.find(x=>x.id===id),next={id:old?.id||uid(),name,amountCents:amount,enabled:old?.enabled!==false,cadence:f.cadence.value,anchorType:f.anchorType.value,anchorDate,createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};if(old)Object.assign(old,next);else state.recurringMustPays.push(next);persist();$('preset-dialog').close();renderRecurringMustPays();flash('Recurring must pay saved.')});$('debt-form').addEventListener('submit',e=>{e.preventDefault();let f=e.currentTarget.elements,start=amountCents(f.startingBalance.value),interest=amountCents(f.interestCharge.value),id=f.id.value,name=f.name.value.trim();if(!name||name.length>100||!Number.isSafeInteger(start)||start<1||!Number.isSafeInteger(interest)||interest<0){$('debt-error').textContent='Enter a name, balance, and valid interest amount.';return}let old=id&&state.debts.find(x=>x.id===id),paid=old?old.startingBalanceCents-old.currentBalanceCents:0,next={id:old?.id||uid(),name,startingBalanceCents:old?.startingBalanceCents||start,currentBalanceCents:Math.max(0,(old?.startingBalanceCents||start)-paid),interestChargeCents:interest,interestCadence:f.interestCadence.value,active:f.active.checked,createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};if(old)Object.assign(old,next);else state.debts.push(next);persist();$('debt-dialog').close();renderDebts();render();flash('Debt saved.')});document.querySelector('[data-preset-close]').addEventListener('click',()=>$('preset-dialog').close());document.querySelector('[data-debt-close]').addEventListener('click',()=>$('debt-dialog').close())}
